<?php
require __DIR__.'/bootstrap.php';require __DIR__.'/workflow-fixture.php';session_start_safe();$_SESSION['admin']=1;$action=$argv[1]??'';
function hrf():array{$m=create_research(['title'=>'[QA] Manual route review '.uid(),'question'=>'Synthetic actual HTTP manual identity regression, not scientific research.','category_id'=>1,'terms'=>1]);moderate('request',$m['id'],'Approved','Owned HTTP regression fixture.');return research($m['id']);}
if($action==='create'){$review=hrf();$ordinary=hrf();foreach(['planning','research','research','synthesis'] as $kind)foreach(wf_tasks($review['id']) as $t)if($t['kind']===$kind&&$t['state']==='Ready'){wf_test_submit($review['id'],$t['id'],wf_test_payload($review['id'],$t),hash('sha256',uid()));break;}$task=array_values(array_filter(wf_tasks($review['id']),fn($t)=>$t['kind']==='review'))[0];echo json_encode(['review'=>['id'=>$review['id'],'slug'=>$review['slug'],'task'=>$task['id']],'ordinary'=>['id'=>$ordinary['id'],'slug'=>$ordinary['slug'],'task'=>wf_tasks($ordinary['id'])[0]['id']]]);exit;}
