if($action==='packet'){$r=research($argv[2]);$t=wf_task($r['id'],$argv[3]);$h=wf_read_handoff($r['id'],$argv[4]);$d=wf_test_payload($r['id'],$t,$t['kind']==='review'?'verified':'completed');$d['submission_key']=$h['nonce'];$d['context_id']=$h['snapshot_id'];$d['task_revision']=$t['revision'];$d['handoff_code']=wf_handoff_code($t,wf_read_snapshot($r['id'],$h['snapshot_id']),$h['nonce']);$d['identity_id']='ffffffffffffffffffffffffffffffff';echo json_encode($d);exit;}
if($action==='state'){$r=research($argv[2]);echo json_encode(['count'=>(int)one('SELECT COUNT(*) n FROM workflow_submissions WHERE research_id=?',[$r['id']])['n'],'result'=>one('SELECT s.id,s.actor_hash,s.submission_method,s.metadata,i.identity_id,a.provider,a.account_hash FROM workflow_submissions s LEFT JOIN research_result_identities i ON i.result_id=s.id LEFT JOIN research_account_identities a ON a.id=i.identity_id WHERE s.research_id=? AND s.task_id=? ORDER BY s.created_at DESC LIMIT 1',[$r['id'],$argv[3]])]);exit;}throw new RuntimeException('Unknown owned HTTP fixture operation');
